{"query":{"query":"topk(
  10,
  max by(workload)(
    label_join(
      sum by(namespace,pod)(
        container_memory_working_set_bytes{
          namespace=~"^(cattle-capi-system|cattle-fleet-local-system|cattle-fleet-system|cattle-system|cattle-turtles-system|cert-manager|fleet-default|kube-system|longhorn-system|monitoring)$",
          pod!="",
          container!="",
          container!="POD"
        }
      ) / 1024 / 1024,
      "workload","","pod"
    )
  )
)","language":"PROMQL","dataset":{"id":"reference-prometheus","title":"reference-prometheus","type":"PROMETHEUS","language":"PROMQL","timeFieldName":"Time","dataSource":{},"signalType":"metrics"}},"filter":[],"indexRefName":"kibanaSavedObjectMeta.searchSourceJSON.index"}

{"query":{"query":"max by(node)(
  (
    100 * (
      1 -
      (
        max by(node,ip)(
          node_memory_MemAvailable_bytes{job="node-exporter",ip!=""}
        )
        /
        max by(node,ip)(
          node_memory_MemTotal_bytes{job="node-exporter",ip!=""}
        )
      )
    )
  )
  and on(node) kube_node_info
)","language":"PROMQL","dataset":{"id":"reference-prometheus","title":"reference-prometheus","type":"PROMETHEUS","language":"PROMQL","timeFieldName":"Time","dataSource":{},"signalType":"metrics"}},"filter":[],"indexRefName":"kibanaSavedObjectMeta.searchSourceJSON.index"}

{"query":{"query":"topk(
