            pod!="",
            container!="",
            container!="POD"
          }[5m]
        )
      ),
      "workload","","pod"
    )
  )
)","language":"PROMQL","dataset":{"id":"reference-prometheus","title":"reference-prometheus","type":"PROMETHEUS","language":"PROMQL","timeFieldName":"Time","dataSource":{},"signalType":"metrics"}},"filter":[],"indexRefName":"kibanaSavedObjectMeta.searchSourceJSON.index"}
